  "settings.steam.presenceHint": "Во время игры Steam показывает, что вы играете в Forged Alliance, и учитывает время; открытый клиент не считается. Для этого должны быть запущены Steam и Forged Alliance в вашей библиотеке Steam. По умолчанию выключено.",
