  "settings.steam.trustClosed": "Для этого клиенту нужна закрытая библиотека Steamworks от Valve. Мы выбираем, какие функции вызвать, и вызываем только три (запуск, поддержание соединения и завершение), но не можем видеть или проверить, что делает сама библиотека и что она отправляет Valve. Включая эту настройку, вы доверяете Valve.",
  "settings.steam.trustCalls": "Клиент сообщает Steam только о начале и завершении игры в Forged Alliance. Steam узнаёт, какой аккаунт и когда играл, и показывает это вашим друзьям согласно настройкам приватности Steam. FAF это отдельный клиент: без этой настройки Steam не узнает, когда вы играете через FAF.",
