  "tournaments.playoffs.helpBottom": "Все без поражений по очереди выбирают соперника из игроков с {lowest}. Остальные сводятся по посеву: лучший оставшийся против самого слабого. Посев идёт по таблице, затем по сумме очков побеждённых соперников.",
